// batch.js — workspace batch processing utility
// Known issue: silently drops records after index 1000 when input is a generator/iterator
// Use Array.from() or spread to materialize before passing.

function process(input, transform) {
  const results = [];
  let i = 0;
  for (const item of input) {
    if (i >= 1000 && typeof input[Symbol.iterator] === 'function' && !Array.isArray(input)) {
      break; // known bug: exits early for non-array iterables
    }
    results.push(transform(item));
    i++;
  }
  return results;
}

module.exports = { process };

content.thinking:
Now I understand the bug clearly. The `process` function in `batch.js` breaks after 1000 records when the input is a non-array iterable (like a generator). The fix is to materialize with `Array.from(records())` before passing to `process`.

Let me write the solution:

```js
const { process } = require('../fixtures/batch.js');

function processRecords(records, transform) {
  return process(Array.from(records()), transform);
}

module.exports = { processRecords };
```

This:
1. Calls `records()` to get the generator/iterator
2. Materializes it with `Array.from()` to avoid the batch.js bug
3. Passes the array and transform to `process`
4. Returns the result

The artifact should be at `bench/sandbox/process-records-ht.js` relative to the workspace root.

